    n = int(sys.stdin.readline().strip())
    rules = []
    for _ in range(4 * n):
        a, b, c = map(int, sys.stdin.readline().strip().split())
        rules.append((a, b, c))

    indegree = [0] * (4 * n)
    graph = [[] for _ in range(n + 1)]
    reverse_graph = [[] for _ in range(n + 1)]

    for i, (a, b, c) in enumerate(rules):
        indegree[i] += 1
        graph[a].append(i)
        reverse_graph[b].append(i)
        reverse_graph[c].append(i)

    queue = deque()
    for i in range(4 * n):
        if indegree[i] == 1:
            queue.append(i)

    order = []
    while queue:
        current = queue.popleft()
        order.append(current + 1)
        a, b, c = rules[current]
        indegree[current] = 0

        for neighbor in graph[a]:
            if indegree[neighbor] > 0:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 1:
                    queue.append(neighbor)

        for neighbor in reverse_graph[b]:
            if indegree[neighbor] > 0:
                indegree[b] -= 1
                if indegree[neighbor] == 1 and neighbor != current:
                    queue.append(neighbor)

        for neighbor in reverse_graph[c]:
            if indegree[neighbor] > 0:
                indegree[c] -= 1
                if indegree[neighbor] == 1  and neighbor != current:
                    queue.append(neighbor)

